def bbox_cells(grid, pred):
    """The subgrid of the bounding box of all cells satisfying pred(cell_value)."""
    pts=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if pred(v)]
    rs=[r for r,_ in pts]; cs=[c for _,c in pts]
    t,b,l,r=min(rs),max(rs),min(cs),max(cs)
    return [[grid[i][j] for j in range(l,r+1)] for i in range(t,b+1)], (t,l)

def rot90ccw(grid):
    """The grid rotated 90 degrees counter-clockwise."""
    return [list(r) for r in zip(*grid)][::-1]

def rot90(grid, k):
    """The grid rotated k*90 degrees clockwise."""
    g=grid
    for _ in range(k%4):
        g=[list(r) for r in zip(*g)][::-1]
    return g

def rot90ccw(grid):
    """The grid rotated 90 degrees counter-clockwise."""
    return rot90(grid, 3)

def upscale(grid, factor):
    """Each cell as a factor x factor block of its color."""
    return [[v for v in row for _ in range(factor)] for row in grid for _ in range(factor)]

def overlay(grid, patch, top, left):
    """The grid with patch stamped in at (top, left); zeros in the patch are transparent."""
    out=[row[:] for row in grid]
    for i,row in enumerate(patch):
        for j,v in enumerate(row):
            if v: out[top+i][left+j]=v
    return out

def recolor_shape_by_scaled_key(grid, shape_color):
    """Replace the shape_color region with the non-background key pattern rotated 90 CCW
    and upscaled so its footprint exactly matches the shape's bounding box."""
    is_key=lambda v: v not in (0, shape_color)
    key,_=bbox_cells(grid, is_key)
    big,(bt,bl)=bbox_cells(grid, lambda v: v==shape_color)
    H,W=len(big),len(big[0])
    for k in range(4):
        rk=rot90(key,k)
        s=H//len(rk)
        if s and len(rk)*s==H and len(rk[0])*s==W:
            cand=upscale(rk,s)
            if [[1 if v else 0 for v in row] for row in cand]==[[1 if v else 0 for v in row] for row in big]:
                return overlay([row[:] for row in grid], cand, bt, bl)
    raise ValueError("no match")

